-- Esquema equivalente ao que o Entity Framework Core (Npgsql) cria com EnsureCreated().
-- Usado SOMENTE para testar os scripts de banco fora da aplicação (CI e testes locais).
-- Na aplicação, as tabelas são criadas pelo próprio EF a partir dos modelos C#.

CREATE TABLE "Lojas" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Nome" character varying(150) NOT NULL,
    "Status" character varying(20) NOT NULL,
    "VencimentoEm" timestamp without time zone NULL,
    "MotivoSuspensao" text NULL,
    "CriadaEm" timestamp without time zone NOT NULL
);

CREATE TABLE "Usuarios" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "UsuarioNome" text NOT NULL,
    "SenhaHash" text NOT NULL,
    "Perfil" character varying(20) NOT NULL,
    "LojaId" integer NULL,
    "Ativo" boolean NOT NULL,
    "DeveTrocarSenha" boolean NOT NULL,
    "UltimoAcessoEm" timestamp without time zone NULL,
    "CriadoEm" timestamp without time zone NOT NULL
);

CREATE TABLE "Sessoes" (
    "Id" character varying(40) NOT NULL PRIMARY KEY,
    "UsuarioId" integer NOT NULL,
    "LojaId" integer NULL,
    "CriadaEm" timestamp without time zone NOT NULL,
    "UltimaAtividade" timestamp without time zone NOT NULL,
    "ExpiraEm" timestamp without time zone NOT NULL,
    "Ip" text NULL,
    "Agente" text NULL,
    "Revogada" boolean NOT NULL,
    "MotivoRevogacao" text NULL,
    "RevogadaEm" timestamp without time zone NULL
);
CREATE INDEX "IX_Sessoes_UsuarioId" ON "Sessoes" ("UsuarioId");

CREATE TABLE "Auditorias" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Data" timestamp without time zone NOT NULL,
    "AtorId" integer NULL,
    "AtorNome" character varying(150) NOT NULL,
    "LojaId" integer NULL,
    "Acao" character varying(80) NOT NULL,
    "Alvo" character varying(200) NOT NULL,
    "Detalhe" text NULL
);

CREATE TABLE "Pacientes" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "LojaId" integer NOT NULL,
    "Etnia" character varying(30) NULL,
    "Nome" character varying(150) NOT NULL,
    "Email" character varying(150) NOT NULL,
    "Telefone" character varying(30) NOT NULL,
    "CPF" character varying(20) NOT NULL
);

CREATE TABLE "Agendamentos" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "LojaId" integer NOT NULL,
    "PacienteNome" character varying(150) NOT NULL,
    "ProfissionalNome" character varying(150) NOT NULL,
    "DataHora" timestamp without time zone NOT NULL,
    "Status" character varying(50) NOT NULL
);

CREATE TABLE "Servicos" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "LojaId" integer NOT NULL,
    "Titulo" character varying(150) NOT NULL,
    "Descricao" character varying(1000) NOT NULL,
    "Valor" numeric NOT NULL
);

CREATE TABLE "Produtos" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "LojaId" integer NOT NULL,
    "Nome" character varying(150) NOT NULL,
    "Preco" numeric NOT NULL,
    "Estoque" integer NOT NULL,
    "Ativo" boolean NOT NULL
);

CREATE TABLE "OrdensServico" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "LojaId" integer NOT NULL,
    "ClienteId" integer NOT NULL,
    "ClienteNome" character varying(150) NOT NULL,
    "ClienteTelefone" character varying(30) NOT NULL,
    "ClienteCPF" character varying(20) NOT NULL,
    "ClienteEmail" character varying(150) NOT NULL,
    "ProfissionalId" integer NOT NULL,
    "ProfissionalNome" character varying(150) NOT NULL,
    "Titulo" character varying(200) NOT NULL,
    "Descricao" character varying(2000) NOT NULL,
    "DataAbertura" timestamp without time zone NOT NULL,
    "DataPrevista" timestamp without time zone NULL,
    "DataConclusao" timestamp without time zone NULL,
    "Status" character varying(50) NOT NULL,
    "Garantia" text NULL,
    "Desconto" numeric NOT NULL,
    "FormaPagamento" character varying(20) NULL,
    "VendedorId" integer NULL,
    "VendedorNome" text NULL
);

CREATE TABLE "OrdemServicoItens" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "OrdemServicoId" integer NOT NULL REFERENCES "OrdensServico" ("Id") ON DELETE CASCADE,
    "ServicoId" integer NOT NULL REFERENCES "Servicos" ("Id") ON DELETE CASCADE,
    "Quantidade" integer NOT NULL,
    "ValorUnitario" numeric NOT NULL
);
CREATE INDEX "IX_OrdemServicoItens_OrdemServicoId" ON "OrdemServicoItens" ("OrdemServicoId");
CREATE INDEX "IX_OrdemServicoItens_ServicoId" ON "OrdemServicoItens" ("ServicoId");

CREATE TABLE "OrdemServicoProdutos" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "OrdemServicoId" integer NOT NULL REFERENCES "OrdensServico" ("Id") ON DELETE CASCADE,
    "ProdutoId" integer NOT NULL,
    "Nome" character varying(150) NOT NULL,
    "Quantidade" integer NOT NULL,
    "ValorUnitario" numeric NOT NULL
);
CREATE INDEX "IX_OrdemServicoProdutos_OrdemServicoId" ON "OrdemServicoProdutos" ("OrdemServicoId");

CREATE TABLE "OrdemServicoImagens" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "OrdemServicoId" integer NOT NULL REFERENCES "OrdensServico" ("Id") ON DELETE CASCADE,
    "NomeArquivo" character varying(255) NOT NULL,
    "ConteudoBase64" text NOT NULL
);
CREATE INDEX "IX_OrdemServicoImagens_OrdemServicoId" ON "OrdemServicoImagens" ("OrdemServicoId");

CREATE TABLE "UsuarioPerfis" (
    "UsuarioId" integer NOT NULL PRIMARY KEY REFERENCES "Usuarios" ("Id") ON DELETE CASCADE,
    "Nome" character varying(200) NOT NULL,
    "Cargo" character varying(200) NOT NULL,
    "Etnia" character varying(30) NULL,
    "FotoPerfilBase64" text NULL
);

CREATE TABLE "UsuarioPreferencias" (
    "UsuarioId" integer NOT NULL PRIMARY KEY REFERENCES "Usuarios" ("Id") ON DELETE CASCADE,
    "Tema" character varying(20) NOT NULL,
    "CorPrincipal" character varying(20) NOT NULL,
    "CompactarTabelas" boolean NOT NULL,
    "FatorFonte" double precision NOT NULL,
    "Libras" boolean NOT NULL,
    "AltoContraste" boolean NOT NULL
);
